export const getPlaceOrderUrl = (slug: string,) => {




  return `/api/stores/${slug}/orders`
}

/**
 * @summary Place a new order on a store
 */
export const placeOrder = async (slug: string,
    orderInput: OrderInput, options?: Parameters<typeof customFetch>[1]): Promise<OrderConfirmation> => {

  return customFetch<OrderConfirmation>(getPlaceOrderUrl(slug),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(orderInput)
  }
);}





export const getPlaceOrderMutationOptions = <TError = ErrorType<ErrorResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof placeOrder>>, TError,{slug: string;data: BodyType<OrderInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof placeOrder>>, TError,{slug: string;data: BodyType<OrderInput>}, TContext> => {

const mutationKey = ['placeOrder'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof placeOrder>>, {slug: string;data: BodyType<OrderInput>}> = (props) => {
          const {slug,data} = props ?? {};

          return  placeOrder(slug,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

